//! Synthetic bounded-projection inputs only. These are not accepted native
//! runs, full Aniflow validator fixtures, actual notes or separation evidence.
use super::*;
fn mono22()->Vec<u8> {let size=4410u32;let mut b=b"RIFF".to_vec();b.extend((36+size).to_le_bytes());b.extend(b"WAVEfmt ");b.extend(16u32.to_le_bytes());b.extend(1u16.to_le_bytes());b.extend(1u16.to_le_bytes());b.extend(22_050u32.to_le_bytes());b.extend(44_100u32.to_le_bytes());b.extend(2u16.to_le_bytes());b.extend(16u16.to_le_bytes());b.extend(b"data");b.extend(size.to_le_bytes());b.resize(44+size as usize,0);b}
fn evidence(root:&Path,recipe:&mut SonicRecipe,analysis:&mut Value,id:&str,bytes:&[u8])->Value {
    let name=format!("{id}.bin");fs::write(root.join(&name),bytes).unwrap();let reference=json!({"id":id,"sha256":hash(bytes),"byte_size":bytes.len()});analysis["artifacts"].as_array_mut().unwrap().push(reference.clone());recipe.analyses[0].evidence_files.push(FileInput {id:id.into(),path:name,sha256:hash(bytes)});reference
}
fn save_analysis(root:&Path,input:&Path,recipe:&mut SonicRecipe,value:&Value) {let bytes=serde_json::to_vec(value).unwrap();fs::write(root.join("analysis.json"),&bytes).unwrap();recipe.analyses[0].file.sha256=hash(&bytes);save(input,recipe);}
fn source(root:&Path,recipe:&mut SonicRecipe,analysis:&mut Value) {
    let wave=mono22();fs::write(root.join("source.wav"),&wave).unwrap();recipe.audio.sha256=hash(&wave);analysis["source"]["artifact"]=json!({"id":"source_audio","sha256":hash(&wave),"byte_size":wave.len()});analysis["source"]["sample_rate_hz"]=json!(22_050);analysis["source"]["frame_count"]=json!(2205);
}
fn provider(value:&mut Value,id:&str,native:&str)->Value {let mut provider=value["providers"][0].clone();provider["id"]=json!(id);provider["provider"]=json!({"id":native,"version":"1.0.0"});value["providers"].as_array_mut().unwrap().push(provider.clone());provider}
fn method()->Value {json!({"sample_rate_hz":22050,"downmix":"none","backend":"onnxruntime_cpu","gpu":false,"pitch_bends":false,"instrument":"unavailable","native_time_quantization":"nearest_microsecond_ties_up","maximum_native_time_error_nanoseconds":500,"velocity_mapping":"round_ties_even_127_times_activation","minimum_pitch":21,"maximum_pitch":108})}
fn midi(root:&Path,input:&Path,recipe:&mut SonicRecipe)->Value {
    let mut analysis=read(&root.join("analysis.json"));source(root,recipe,&mut analysis);let technical=evidence(root,recipe,&mut analysis,"technical",b"synthetic technical only");let upstream=evidence(root,recipe,&mut analysis,"analysis",b"synthetic upstream only");
    let provider=provider(&mut analysis,"midi_provider","org.egohygiene.aniflow.audio-midi");let confidence=json!({"kind":"unavailable","reason":"Note activations and MIDI velocities are not calibrated confidence; inferred notes are unreviewed candidates."});
    let report=json!({"schema":"aniflow.audio-midi/v1","source":analysis["source"],"scope":{"channels":[0],"stem_id":null},"technical_artifact":technical,"upstream_analysis_artifact":upstream,"raw_observation":{"id":"midi_observation","sha256":"d".repeat(64),"byte_size":400},"provider":provider["provider"],"implementation_sha256":provider["implementation_sha256"],"configuration_sha256":provider["configuration_sha256"],"provider_lock_sha256":"e".repeat(64),"settings":{"private_marker":"Private MIDI settings payload"},"probe":{},"commands":[],"method":method(),"provenance":"probabilistic","confidence":confidence,
        "result":{"status":"candidate","observation":{"native":{"schema":"aniflow.audio-midi-observation/v1","sample_rate_hz":22050,"channels":1,"sample_frames":2205,"duration_microseconds":100000,"notes":[{"start_microseconds":0,"end_microseconds":50000,"pitch":60,"velocity":64,"activation":0.5}]},"notes":[{"id":"note_000000","start":{"numerator":0,"denominator":1},"end":{"numerator":1,"denominator":20},"start_tick":0,"end_tick":96,"pitch":60,"velocity":64,"activation":0.5}]}}});
    evidence(root,recipe,&mut analysis,"midi",&serde_json::to_vec(&report).unwrap());
    let refs=json!(["source_audio","technical","analysis","midi"]);analysis["capabilities"].as_array_mut().unwrap().push(json!({"capability":{"id":"aniflow/audio-midi-extraction","version":"1.0.0"},"status":"complete","provider_evidence_ids":["midi_provider"],"evidence_artifact_ids":refs,"diagnostic_ids":[]}));
    analysis["semantic_artifacts"]=json!([{"artifact_id":"midi","capability_id":"aniflow/audio-midi-extraction","kind":"candidate_midi","provenance":{"class":"probabilistic","confidence":confidence,"provider_evidence_id":"midi_provider","evidence_artifact_ids":refs},"authority":null}]);
    recipe.analyses[0].midi_context=Some(sonic::MidiContext {artifact_id:"midi".into(),maximum_notes:4});save_analysis(root,input,recipe,&analysis);report
}
fn replace_report(root:&Path,input:&Path,recipe:&mut SonicRecipe,id:&str,change:impl FnOnce(&mut Value)) {
    let mut analysis=read(&root.join("analysis.json"));let file=recipe.analyses[0].evidence_files.iter_mut().find(|f|f.id==id).unwrap();let path=root.join(&file.path);let mut value=read(&path);change(&mut value);let bytes=serde_json::to_vec(&value).unwrap();fs::write(path,&bytes).unwrap();file.sha256=hash(&bytes);
    let reference=analysis["artifacts"].as_array_mut().unwrap().iter_mut().find(|r|r["id"]==id).unwrap();reference["sha256"]=json!(hash(&bytes));reference["byte_size"]=json!(bytes.len());save_analysis(root,input,recipe,&analysis);
}
#[test]
fn explicit_notes_keep_exact_report_times_and_unavailable_confidence_without_payload_leak() {
    let root=tempfile::tempdir().unwrap();let (input,mut recipe)=fixture(root.path());midi(root.path(),&input,&mut recipe);let plan=sonic::plan(&input,None,token()).unwrap();assert_eq!(plan.analyses[0]["normalized_note_facts"],1);
    let output=root.path().join("notes");sonic::build(&request(&input,&output),None,token()).unwrap();let dna=read(&output.join("sonic-dna.json"));let note=dna["provider_extensions"]["renderflow.sonic"]["facts"].as_array().unwrap().iter().find(|r|r["dimension"]=="sonic.score.inferred_note").unwrap();assert_eq!(note["value"]["end_seconds"],json!({"numerator":1,"denominator":20}));assert_eq!(note["confidence"]["kind"],"unavailable");assert_eq!(note["value"]["activation_is_confidence"],false);assert_eq!(note["evidence"]["native_raw_bytes_observed"],false);
    for name in ["sonic-dna.json","audio-description.json","prompt-guidance.json"] {assert!(!fs::read_to_string(output.join(name)).unwrap().contains("Private MIDI settings"));}
}
#[test]
fn midi_is_unprojected_without_explicit_selection_and_rejects_bad_clock_or_mapping() {
    let root=tempfile::tempdir().unwrap();let (input,mut recipe)=fixture(root.path());midi(root.path(),&input,&mut recipe);recipe.analyses[0].midi_context=None;save(&input,&recipe);let plan=sonic::plan(&input,None,token()).unwrap();assert_eq!(plan.analyses[0]["unprojected"]["semantic_artifacts"],1);assert_eq!(plan.analyses[0]["normalized_note_facts"],0);
    for mutation in 0..4 {let root=tempfile::tempdir().unwrap();let (input,mut recipe)=fixture(root.path());midi(root.path(),&input,&mut recipe);replace_report(root.path(),&input,&mut recipe,"midi",|v|match mutation {0=>v["source"]["frame_count"]=json!(2206),1=>v["result"]["observation"]["notes"][0]["end"]["denominator"]=json!(19),2=>v["result"]["observation"]["notes"][0]["activation"]=json!(0.8),_=>v["result"]["observation"]["native"]["notes"][0]["end_microseconds"]=json!(100001)});assert!(sonic::plan(&input,None,token()).is_err());}
}
#[test]
fn selected_note_limit_and_uncertainty_cannot_be_replaced_by_truncation_or_score_confidence() {
    for mutation in 0..2 {let root=tempfile::tempdir().unwrap();let (input,mut recipe)=fixture(root.path());midi(root.path(),&input,&mut recipe);
        if mutation==0 {recipe.analyses[0].midi_context.as_mut().unwrap().maximum_notes=1;replace_report(root.path(),&input,&mut recipe,"midi",|v|{let mut raw=v["result"]["observation"]["native"]["notes"][0].clone();raw["pitch"]=json!(64);v["result"]["observation"]["native"]["notes"].as_array_mut().unwrap().push(raw);let mut note=v["result"]["observation"]["notes"][0].clone();note["id"]=json!("note_000001");note["pitch"]=json!(64);v["result"]["observation"]["notes"].as_array_mut().unwrap().push(note);});}
        else {replace_report(root.path(),&input,&mut recipe,"midi",|v|v["confidence"]=json!({"kind":"calibrated","score":0.5}));}
        assert!(sonic::plan(&input,None,token()).is_err());
    }
}
fn stem(root:&Path,input:&Path,recipe:&mut SonicRecipe) {
    let mut analysis=read(&root.join("analysis.json"));source(root,recipe,&mut analysis);let original=json!({"artifact":{"id":"original_mix","sha256":"f".repeat(64),"byte_size":19244},"stream_index":0,"sample_rate_hz":48000,"channels":2,"frame_count":4800,"origin":{"numerator":0,"denominator":1},"stem":null});
    analysis["source"]["stem"]=json!({"id":"voice_layer","original_mix":original["artifact"],"relationship_evidence_id":"stem_lineage"});for o in analysis["observations"].as_array_mut().unwrap(){o["scope"]["stem_id"]=json!("voice_layer");}
    let upstream=evidence(root,recipe,&mut analysis,"analysis",b"synthetic upstream");let relationship=evidence(root,recipe,&mut analysis,"separation_evidence",b"synthetic separation reference");let mut authority=Vec::new();for name in ["plan","manifest","checkpoint","lock","report","validation_0","validation_1"] {authority.push(evidence(root,recipe,&mut analysis,&format!("stem_authority_{name}"),b"Private stem authority payload"));}
    let provider=provider(&mut analysis,"stem_provider","org.egohygiene.aniflow.audio-stem");let report=json!({"schema":"aniflow.audio-stem-lineage/v1","lineage":{"original_mix":original,"selected_stem":analysis["source"],"stem_id":"voice_layer","source_stage_id":"separator","source_mix_artifact_id":"mix","source_stem_artifact_id":"voice_layer","source_stem_port":"voice","scope":{"channels":[0],"stem_id":"voice_layer"},"range":{"start":0,"end":2205},"relationship_evidence":relationship,"authority_artifacts":authority,"source_plan_sha256":"a".repeat(64),"source_checkpoint_sha256":"b".repeat(64),"source_provider":{"id":"org.example.synthetic","version":"1.0.0"},"source_provider_lock_sha256":"c".repeat(64),"source_implementation_sha256":"d".repeat(64),"source_configuration_sha256":"e".repeat(64),"duration_tolerance_milliseconds":20,"timing_basis":"zero_origin_duration_only"},"upstream_analysis_artifact":upstream,"provider":provider["provider"],"implementation_sha256":provider["implementation_sha256"],"configuration_sha256":provider["configuration_sha256"],"provider_lock_sha256":"a".repeat(64)});
    evidence(root,recipe,&mut analysis,"stem_lineage",&serde_json::to_vec(&report).unwrap());analysis["capabilities"].as_array_mut().unwrap().push(json!({"capability":{"id":"aniflow/audio-stem-lineage","version":"1.0.0"},"status":"complete","provider_evidence_ids":["stem_provider"],"evidence_artifact_ids":["source_audio","original_mix","separation_evidence","stem_lineage"],"diagnostic_ids":[]}));recipe.analyses[0].stem_context=Some(sonic::StemContext {lineage_artifact_id:"stem_lineage".into()});save_analysis(root,input,recipe,&analysis);
}
#[test]
fn stem_metadata_keeps_distinct_clocks_and_never_claims_original_mix_sample_alignment() {
    let root=tempfile::tempdir().unwrap();let (input,mut recipe)=fixture(root.path());stem(root.path(),&input,&mut recipe);let output=root.path().join("stem");sonic::build(&request(&input,&output),None,token()).unwrap();let dna=read(&output.join("sonic-dna.json"));let fact=dna["provider_extensions"]["renderflow.sonic"]["facts"].as_array().unwrap().iter().find(|r|r["dimension"]=="sonic.arrangement.declared_stem_relationship").unwrap();assert_eq!(fact["value"]["selected_source_sample_rate_hz"],22050);assert_eq!(fact["value"]["original_mix"]["sample_rate_hz"],48000);assert_eq!(fact["value"]["sample_alignment_to_original_mix"],"not_established");assert_eq!(fact["value"]["original_mix_bytes_observed"],false);assert!(!fs::read_to_string(output.join("sonic-dna.json")).unwrap().contains("Private stem authority payload"));
}
#[test]
fn stem_selection_mismatch_bad_duration_and_missing_retained_authority_refuse() {
    for mutation in 0..3 {let root=tempfile::tempdir().unwrap();let (input,mut recipe)=fixture(root.path());stem(root.path(),&input,&mut recipe);match mutation {0=>{recipe.analyses[0].stem_context=None;save(&input,&recipe);},1=>replace_report(root.path(),&input,&mut recipe,"stem_lineage",|v|v["lineage"]["original_mix"]["frame_count"]=json!(6000)),_=>{fs::remove_file(root.path().join("stem_authority_plan.bin")).unwrap();}}assert!(sonic::plan(&input,None,token()).is_err());}
}
